package com.sklad.skladproject.config

import io.swagger.v3.oas.models.OpenAPI
import io.swagger.v3.oas.models.info.Info
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration

// Metadata for the OpenAPI document generated by springdoc from the controllers.
// Document: /v3/api-docs (JSON), /v3/api-docs.yaml (YAML). UI: /swagger-ui.html
@Configuration
class OpenApiConfig {
    @Bean
    fun skladOpenApi(): OpenAPI = OpenAPI().info(
        Info()
            .title("Sklad API")
            .version("1.0")
            .description(
                """
                Warehouse backend. Reference data (items, measure units, currencies, packages)
                is maintained through `add-*` / `get-*` endpoints; purchases are recorded into
                the purchase operation history and read back by date, page by page.

                Conventions:
                * All `add-*` reference endpoints are idempotent: posting an existing record returns it (with its id) and does not create a duplicate.
                * Validation problems are reported as HTTP 400 with a `message` listing every detected error, separated by `; `.
                * Reference `add-*` endpoints report database failures as HTTP 500; `add-purchase-operation` still answers `false` for them.
                """.trimIndent()
            )
    )
}
